  ON DUPLICATE KEY UPDATE name = VALUES(name), duration_months = VALUES(duration_months);

ON DUPLICATE KEY UPDATE
  roll_no = VALUES(roll_no),
  name = VALUES(name),
  email = VALUES(email),
  phone = VALUES(phone),
  dob = VALUES(dob),
  gender = VALUES(gender),
  address = VALUES(address),
  course_id = VALUES(course_id);
